package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.configuration.RuntimeConfigurationRepository.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.time.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="MOP_RUN_RUNTIME_CONFIG_TESTS",matches="true")
class PostgresRuntimeConfigurationIntegrationTest {
 static HikariDataSource pool;static PostgresPlatformRepository platform;static PostgresRuntimeConfigurationRepository runtime;static ObjectMapper mapper=new ObjectMapper();
 static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002",HASH="a".repeat(64);static String actor,reviewer;static Access access;
 @BeforeAll static void connect()throws Exception{var config=new HikariConfig();config.setJdbcUrl(System.getenv("SPRING_DATASOURCE_URL"));assertTrue(config.getJdbcUrl().matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));config.setUsername("mop_test_runtime");config.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));config.setMaximumPoolSize(6);pool=new HikariDataSource(config);platform=new PostgresPlatformRepository(pool,mapper);runtime=new PostgresRuntimeConfigurationRepository(pool,platform,mapper);assertTrue(runtime.readinessProblems().isEmpty());actor=platform.users().stream().filter(u->u.displayName().equals("平台管理员（测试身份）")).findFirst().orElseThrow().id();reviewer=platform.users().stream().filter(u->u.displayName().equals("配置复核管理员（测试身份）")).findFirst().orElseThrow().id();access=access(actor,TENANT);}
 @AfterAll static void close(){if(pool!=null)pool.close();}
 static Access access(String a,String tenant){return new Access(tenant,a,platform.membership(a,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
 static Object transaction(String actor,String key,String hash,java.util.function.Supplier<Object> command){var m=platform.membership(actor,TENANT).orElseThrow();return platform.idempotentAuthorized(actor,TENANT,"POST /integration/runtime-config",key,hash,m.permissionVersion(),()->{},command);}
 static Map<String,Object> approved(String key,int value){var evidence=List.of(Map.of("reference","document-ref:synthetic-config-runtime","title","SYNTHETIC runtime configuration test, not customer approval","sha256",HASH));Map<String,Object> r=(Map<String,Object>)transaction(actor,UUID.randomUUID().toString(),HASH,()->platform.createConfigurationRevision(TENANT,actor,key,Map.of("synthetic_run",UUID.randomUUID().toString(),"value",value),"SYNTHETIC_RUNTIME_CONFIG",evidence));String id=r.get("id").toString();transaction(actor,UUID.randomUUID().toString(),HASH,()->platform.transitionConfigurationRevision(TENANT,actor,id,1,"SUBMIT",null));return (Map<String,Object>)transaction(reviewer,UUID.randomUUID().toString(),HASH,()->platform.transitionConfigurationRevision(TENANT,reviewer,id,2,"APPROVE","SYNTHETIC_RUNTIME_CONFIG"));}
 static long version(String key){return ((Number)runtime.read(access,key).get("latest_version")).longValue();}
 static Map<String,Object> publish(String key,Command command,String idempotency){return mapper.convertValue(platform.idempotentAuthorized(actor,TENANT,"POST /integration/runtime-config/"+key,idempotency,HASH,access.permissionVersion(),()->runtime.authorizeCommand(access,key),()->runtime.publish(access,key,command,HASH)),LinkedHashMap.class);}
 static Command proposal(String key,Map<String,Object> r){return new Command(version(key),"PUBLISH",r.get("id").toString(),((Number)r.get("version")).longValue(),null,"IMMEDIATE",null,null,"SYNTHETIC_RUNTIME_CONFIG");}
 static Object wire(Object value){try{return mapper.readTree(mapper.writeValueAsBytes(value));}catch(Exception e){throw new IllegalStateException(e);}}
 static void guard(String key){var c=runtime.read(access,key);var selected=(Map<?,?>)c.get("selected_release");if(selected!=null)assertEquals("SYNTHETIC_RUNTIME_CONFIG",selected.get("reason"),"Never overwrite non-test runtime configuration");}
 static void disable(String key){publish(key,new Command(version(key),"DISABLE",null,null,null,"IMMEDIATE",null,null,"SYNTHETIC_RUNTIME_CONFIG"),UUID.randomUUID().toString());}
 @Test void publishReplayRollbackAndDisableKeepImmutableHistoryAndRegistry(){String key="scope.extensions";guard(key);var registry=platform.configuration(key);var first=approved(key,1);var command=proposal(key,first);String request=UUID.randomUUID().toString();var release=publish(key,command,request);assertEquals("ACTIVE",runtime.read(access,key).get("status"));assertEquals(wire(release),wire(publish(key,command,request)));var second=publish(key,proposal(key,approved(key,2)),UUID.randomUUID().toString());assertEquals(command.expectedVersion()+2,((Number)second.get("version")).longValue());var rollback=publish(key,new Command(version(key),"ROLLBACK",null,null,release.get("id").toString(),"IMMEDIATE",null,null,"SYNTHETIC_RUNTIME_CONFIG"),UUID.randomUUID().toString());assertEquals(wire(release.get("value")),wire(rollback.get("value")));assertEquals(registry,platform.configuration(key));assertEquals(false,rollback.get("production_approved"));assertEquals("UNVERIFIED",rollback.get("customer_confirmation_status"));disable(key);assertNull(runtime.read(access,key).get("effective_value"));assertEquals("DISABLED",runtime.read(access,key).get("status"));assertEquals(wire(release),wire(runtime.release(access,key,release.get("id").toString())));}
 static void waitUntil(String key,Instant target)throws Exception{for(int n=0;n<30;n++){Instant at=Instant.parse(runtime.read(access,key).get("observed_at").toString());if(!at.isBefore(target))return;Thread.sleep(Math.min(2000,Math.max(100,Duration.between(at,target).toMillis()+50)));}throw new IllegalStateException("Database clock did not reach schedule");}
 @Test void scheduledReleaseDoesNotReplaceCurrentUntilDueAndExpiryDoesNotResurrectOldValue()throws Exception{String key="scope.annual_review";guard(key);publish(key,proposal(key,approved(key,1)),UUID.randomUUID().toString());var next=approved(key,2);Instant now=Instant.parse(runtime.read(access,key).get("observed_at").toString()),effective=now.plusSeconds(10),expires=now.plusSeconds(20);var scheduled=publish(key,new Command(version(key),"PUBLISH",next.get("id").toString(),3L,null,"SCHEDULED",effective,expires,"SYNTHETIC_RUNTIME_CONFIG"),UUID.randomUUID().toString());assertTrue(((Number)((Map<?,?>)runtime.read(access,key).get("selected_release")).get("version")).longValue()<((Number)scheduled.get("version")).longValue());waitUntil(key,effective);assertEquals(scheduled.get("id"),((Map<?,?>)runtime.read(access,key).get("selected_release")).get("id"));waitUntil(key,expires);assertEquals("EXPIRED",runtime.read(access,key).get("status"));assertNull(runtime.read(access,key).get("effective_value"));disable(key);}
 @Test void concurrentSameHeadHasOneWinnerAndOldCasIsRejected()throws Exception{String key="scope.feishu";guard(key);var command=proposal(key,approved(key,3));ExecutorService threads=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Integer>> results=new ArrayList<>();for(int n=0;n<2;n++)results.add(threads.submit(()->{start.await();try{publish(key,command,UUID.randomUUID().toString());return 200;}catch(DomainException e){return e.status;}}));start.countDown();assertEquals(Set.of(200,409),Set.of(results.get(0).get(30,TimeUnit.SECONDS),results.get(1).get(30,TimeUnit.SECONDS)));}finally{threads.shutdownNow();disable(key);}}
 @Test void crossTenantWrongKeyAndUnapprovedSourceNeverPublish(){String key="scope.extensions";guard(key);var r=approved(key,4);assertEquals(404,assertThrows(DomainException.class,()->runtime.release(access(actor,OTHER),key,r.get("id").toString())).status);assertEquals(404,assertThrows(DomainException.class,()->publish("scope.feishu",new Command(version("scope.feishu"),"PUBLISH",r.get("id").toString(),3L,null,"IMMEDIATE",null,null,"SYNTHETIC_RUNTIME_CONFIG"),UUID.randomUUID().toString())).status);assertEquals(409,assertThrows(DomainException.class,()->publish(key,new Command(version(key),"PUBLISH",r.get("id").toString(),2L,null,"IMMEDIATE",null,null,"SYNTHETIC_RUNTIME_CONFIG"),UUID.randomUUID().toString())).status);}
 @Test void runtimeRoleCannotUpdateOrDeletePublicationRows()throws Exception{try(var c=pool.getConnection()){for(String sql:List.of("UPDATE public.mop_runtime_configuration_release SET reason='changed' WHERE false","DELETE FROM public.mop_runtime_configuration_release WHERE false"))assertThrows(SQLException.class,()->{try(var s=c.createStatement()){s.execute(sql);}});}}
 @Test void failedTransactionLeavesNoPublicationOrReplayReceipt(){String key="scope.extensions";guard(key);var command=proposal(key,approved(key,5));long before=version(key);String request=UUID.randomUUID().toString();assertThrows(IllegalStateException.class,()->platform.idempotentAuthorized(actor,TENANT,"POST /integration/runtime-failure",request,HASH,access.permissionVersion(),()->runtime.authorizeCommand(access,key),()->{runtime.publish(access,key,command,HASH);throw new IllegalStateException("synthetic rollback");}));assertEquals(before,version(key));assertEquals("retried",platform.idempotent(actor,TENANT,"POST /integration/runtime-failure",request,HASH,access.permissionVersion(),()->"retried"));}
}
